-- PT111-S1-Q5. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT111-S1-Q5$batch05$ AND q.stimulus=$batch05$Proponent: Irradiation of food by gamma rays would keep it from spoiling before it reaches the consumer in food stores. The process leaves no radiation behind, and vitamin losses are comparable to those that occur in cooking, so there is no reason to reject irradiation on the grounds of nutrition or safety. Indeed, it kills harmful Salmonella bacteria, which in contaminated poultry have caused serious illness to consumers.
Opponent: The irradiation process has no effect on the bacteria that cause botulism, a very serious form of food poisoning, while those that cause bad odors that would warn consumers of botulism are killed. Moreover, Salmonella and the bacteria that cause botulism can easily be killed in poultry by using a safe chemical dip.$batch05$ AND q.prompt=$batch05$The opponent's argument proceeds by$batch05$ AND q.correct_choice=$batch05$E$batch05$) THEN RAISE EXCEPTION 'Question changed: PT111-S1-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT111-S1-Q5$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S1-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT111-S1-Q5$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Opponent, implied) Irradiation is not the right way to protect poultry.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Irradiation does not kill the bacteria behind botulism, and it kills the bacteria whose bad smell would warn consumers. A safe chemical dip kills both Salmonella and the botulism bacteria.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The proponent's selling point is that irradiation kills Salmonella. The opponent keeps that benefit and shows a better way to get it. The dip kills Salmonella too, without the hidden danger: botulism with no warning smell. Same advantage, minus the risk.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Offering another way to get the proponent's benefit without a particular risk.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT111-S1-Q5$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$No key term is ambiguous.$batch05$), ($batch05$B$batch05$, $batch05$The opponent does not show the proponent contradicting themselves.$batch05$), ($batch05$C$batch05$, $batch05$This is the most popular wrong answer. It sees two remedies in the opponent's response, irradiation and the dip. But the opponent finds a downside in only one of them. The dip is called *safe*, and that is the whole point.$batch05$), ($batch05$D$batch05$, $batch05$The perspective stays on consumers throughout. Producers never come up.$batch05$), ($batch05$E$batch05$, $batch05$The advantage is killing Salmonella. The alternative is the chemical dip. The disadvantage avoided is undetected botulism.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT111-S1-Q5$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
